/**
 * Guards the generated BYO wrangler override (`wrangler.byo.jsonc`).
 *
 * The generated file REPLACES the committed `wrangler.jsonc` on deploy, so a
 * missing Durable Object migration tag or a stale compatibility date silently
 * breaks deploys for real users. This test pins the generated config against
 * the committed one so the two cannot drift.
 *
 * It also asserts the committed top-level config stays BYO-safe: no Phorma
 * account id, no Phorma R2 bucket.
 *
 * Pure - no worker, no network.
 * Run: node cloud/test/deploy-config.test.mjs
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..');

let failures = 0;
function check(name, condition, detail) {
  if (condition) {
    console.log(`  PASS  ${name}`);
  } else {
    failures += 1;
    console.error(`  FAIL  ${name}${detail ? ` - ${detail}` : ''}`);
  }
}

/** Strips `//` comments so JSONC can be parsed. Good enough for our own file. */
function parseJsonc(text) {
  return JSON.parse(text.replace(/^\s*\/\/.*$/gm, ''));
}

const committedText = readFileSync(join(repoRoot, 'cloud', 'wrangler.jsonc'), 'utf8');
const committed = parseJsonc(committedText);

/**
 * Every Durable Object class the worker exports, in migration order. Sourced
 * from `src/index.ts` rather than hardcoded, so exporting a new class without
 * binding it (or without a migration) fails here instead of at deploy.
 */
const EXPECTED_DO_CLASSES = (() => {
  const indexText = readFileSync(join(repoRoot, 'cloud', 'src', 'index.ts'), 'utf8');
  const match = /export \{([^}]+)\}/.exec(indexText);
  return (match?.[1] ?? '')
    .split(',')
    .map(name => name.trim())
    .filter(Boolean);
})();

/** A migration list reduced to `[tag, classes]` pairs for order-sensitive comparison. */
function migrationShape(migrations) {
  return (migrations ?? []).map(entry => [entry.tag, entry.new_sqlite_classes ?? []]);
}

// ── 1: the committed top-level config is BYO-safe ────────────────────────────
console.log('Committed wrangler.jsonc: BYO-safe');
{
  check(
    'no account_id at the top level (would break every BYO deploy)',
    committed.account_id === undefined,
    `found ${committed.account_id}`,
  );
  check(
    'no r2_buckets at the top level (phorma-releases is ours, not theirs)',
    committed.r2_buckets === undefined,
    JSON.stringify(committed.r2_buckets),
  );
  check('a worker name is still provided as a default', typeof committed.name === 'string');
  check('the entry point is set', committed.main === 'src/index.ts');
  // Asserted as SETS rather than counts: adding a Durable Object should fail
  // this suite only where a source actually drifted, not on a magic number.
  const boundClasses = (committed.durable_objects?.bindings ?? []).map(b => b.class_name);
  check(
    'every Durable Object class this worker exports is bound',
    JSON.stringify(boundClasses) === JSON.stringify(EXPECTED_DO_CLASSES),
    JSON.stringify(boundClasses),
  );
  check(
    'migrations cover every bound class, one tag each, in order',
    JSON.stringify(migrationShape(committed.migrations)) ===
      JSON.stringify(EXPECTED_DO_CLASSES.map((cls, i) => [`v${i + 1}`, [cls]])),
    JSON.stringify(committed.migrations),
  );

  // Hosted keeps everything it needs, including its own pinned account.
  const hosted = committed.env?.hosted;
  check('hosted env exists', !!hosted);
  check('hosted pins the Phorma account id', typeof hosted?.account_id === 'string');
  check('hosted keeps the RELEASES bucket', hosted?.r2_buckets?.length === 1);
  check('hosted keeps D1', hosted?.d1_databases?.length === 1);
  check('hosted keeps KV', hosted?.kv_namespaces?.length === 1);
  check(
    'hosted mirrors the top-level Durable Object bindings',
    JSON.stringify((hosted?.durable_objects?.bindings ?? []).map(b => b.class_name)) ===
      JSON.stringify(EXPECTED_DO_CLASSES),
    JSON.stringify(hosted?.durable_objects?.bindings),
  );
  check(
    'hosted mirrors the top-level migrations',
    JSON.stringify(migrationShape(hosted?.migrations)) ===
      JSON.stringify(migrationShape(committed.migrations)),
    JSON.stringify(hosted?.migrations),
  );
  check('hosted sets PHORMA_MODE', hosted?.vars?.PHORMA_MODE === 'hosted');
}

// ── 2: the generator mirrors the committed config ────────────────────────────
// The service is Angular-decorated, so rather than importing it (which would
// drag in @angular/core), assert against the constants it declares. This keeps
// the test dependency-free while still failing if the two files drift.
console.log('\nGenerated override: mirrors the committed config');
{
  const serviceText = readFileSync(
    join(repoRoot, 'frontend', 'src', 'app', 'core', 'deploy-config.service.ts'),
    'utf8',
  );

  // The generated override REPLACES the committed config, so a class or a
  // migration tag missing here silently drops a binding from every BYO deploy.
  //
  // Parsed as PAIRS, not as two independent substring searches. `includes("tag:
  // 'v1'") && includes("'WorkflowAgent'")` is true even when v1 is attached to
  // the wrong class - swapping the classes on v1 and v3 passed the previous
  // version of this check, and a scrambled `new_sqlite_classes` tag breaks every
  // BYO deploy exactly the way a missing one does.
  const generatorMigrations = (() => {
    const block = /const DO_MIGRATIONS = \[([\s\S]*?)\]\s*as const;/.exec(serviceText);
    if (!block) return null;
    const pairs = [];
    const entry = /\{\s*tag:\s*'([^']+)'\s*,\s*new_sqlite_classes:\s*\[([^\]]*)\]/g;
    let match;
    while ((match = entry.exec(block[1])) !== null) {
      const classes = match[2]
        .split(',')
        .map(name => name.trim().replace(/^'|'$/g, ''))
        .filter(Boolean);
      pairs.push([match[1], classes]);
    }
    return pairs;
  })();

  check('generator declares a parseable DO_MIGRATIONS list', Array.isArray(generatorMigrations));
  check(
    'generator pairs every migration tag with the SAME class as the committed config',
    JSON.stringify(generatorMigrations) === JSON.stringify(migrationShape(committed.migrations)),
    JSON.stringify(generatorMigrations),
  );
  check(
    'generator uses the committed compatibility date',
    serviceText.includes(`'${committed.compatibility_date}'`),
    committed.compatibility_date,
  );
  check(
    'generator uses the committed compatibility flags',
    committed.compatibility_flags.every(flag => serviceText.includes(`'${flag}'`)),
    JSON.stringify(committed.compatibility_flags),
  );
  check(
    'generator uses the committed default worker name',
    serviceText.includes(`'${committed.name}'`),
    committed.name,
  );
  check(
    'generator does NOT emit an env block (hosted is ours)',
    !/\benv\s*:/.test(serviceText.split('buildOverrideConfig')[1] ?? ''),
  );
  // Only the ASSIGNMENT matters; the service mentions `r2_buckets` in a comment
  // explaining why it is deliberately omitted.
  check(
    'generator does NOT emit r2_buckets',
    !/config\[['"]r2_buckets['"]\]|r2_buckets\s*:/.test(serviceText),
  );
  check(
    'generated file is gitignored at the repo root',
    readFileSync(join(repoRoot, '.gitignore'), 'utf8').includes('wrangler.byo.jsonc'),
  );
  check(
    'generated file is gitignored in cloud/',
    readFileSync(join(repoRoot, 'cloud', '.gitignore'), 'utf8').includes('wrangler.byo.jsonc'),
  );
}

// ── 3: build stamps track the manifests ──────────────────────────────────────
// The worker bundle and the Angular app cannot import JSON, so each carries a
// literal. A stale literal makes the worker lie about its version, which would
// either nag an up-to-date user or hide a genuinely old deploy.
console.log('\nBuild stamps: in lockstep with the manifests');
{
  const constOf = path => {
    const match = /export const \w+ = '([^']*)';/.exec(readFileSync(join(repoRoot, path), 'utf8'));
    return match?.[1] ?? null;
  };
  const manifestOf = path => JSON.parse(readFileSync(join(repoRoot, path), 'utf8')).version;

  const cloudManifest = manifestOf('cloud/package.json');
  const frontendManifest = manifestOf('frontend/package.json');
  const workerBuild = constOf('cloud/src/build-info.ts');
  const appVersion = constOf('frontend/src/app/core/app-version.ts');

  check('WORKER_BUILD is a version string', !!workerBuild, String(workerBuild));
  check('APP_VERSION is a version string', !!appVersion, String(appVersion));
  check(
    'WORKER_BUILD matches cloud/package.json',
    workerBuild === cloudManifest,
    `${workerBuild} vs ${cloudManifest}`,
  );
  check(
    'APP_VERSION matches frontend/package.json',
    appVersion === frontendManifest,
    `${appVersion} vs ${frontendManifest}`,
  );

  // The release script must know about both, or a release silently ships a
  // stamp from the previous version.
  const releaseScript = readFileSync(join(repoRoot, 'scripts', 'release.mjs'), 'utf8');
  check('release.mjs bumps the worker stamp', releaseScript.includes('cloud/src/build-info.ts'));
  check(
    'release.mjs bumps the app version',
    releaseScript.includes('frontend/src/app/core/app-version.ts'),
  );
}

console.log(failures === 0 ? '\nAll checks passed.' : `\n${failures} check(s) FAILED.`);
process.exit(failures === 0 ? 0 : 1);
